import{_ as a,o,c as r,a2 as t}from"./chunks/framework.CWASMpdJ.js";const u=JSON.parse('{"title":"Časté otázky","description":"Odpovede na časté otázky o Nette API - 404 pre zaregistrované endpointy, 500 pre správne odpovede, tokeny, CORS, logovanie, OpenAPI a upgrade.","frontmatter":{"title":"Časté otázky","description":"Odpovede na časté otázky o Nette API - 404 pre zaregistrované endpointy, 500 pre správne odpovede, tokeny, CORS, logovanie, OpenAPI a upgrade."},"headers":[],"relativePath":"sk/faq.md","filePath":"sk/faq.md","lastUpdated":1793042989000}'),i={name:"sk/faq.md"};function p(n,e,d,s,l,c){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="caste-otazky" tabindex="-1">Časté otázky <a class="header-anchor" href="#caste-otazky" aria-label="Permalink to &quot;Časté otázky&quot;">​</a></h1><h2 id="preco-moj-zaregistrovany-endpoint-vracia-404" tabindex="-1">Prečo môj zaregistrovaný endpoint vracia 404? <a class="header-anchor" href="#preco-moj-zaregistrovany-endpoint-vracia-404" aria-label="Permalink to &quot;Prečo môj zaregistrovaný endpoint vracia 404?&quot;">​</a></h2><p>Metóda, verzia, balík a akcia požiadavky sa musia presne zhodovať s <code>EndpointIdentifier</code> a routa musí viesť na <code>Api:Api:default</code>. Pozrite si <a href="/nette-api/pr-preview/pr-184/sk/guide/getting-started.html">Začíname</a>.</p><h2 id="moj-handler-vracia-spravne-data-ale-klient-dostane-500-preco" tabindex="-1">Môj handler vracia správne dáta, ale klient dostane 500. Prečo? <a class="header-anchor" href="#moj-handler-vracia-spravne-data-ale-klient-dostane-500-preco" aria-label="Permalink to &quot;Môj handler vracia správne dáta, ale klient dostane 500. Prečo?&quot;">​</a></h2><p>Odpoveď nezodpovedala žiadnemu deklarovanému výstupu a validácia výstupov je zapnutá. Pozrite sa na <code>detail</code>, alebo si prečítajte <a href="/nette-api/pr-preview/pr-184/sk/guide/outputs.html#kedy-sa-vystupy-validuju">Výstupy</a>.</p><h2 id="preco-produkcia-hovori-len-„wrong-input" tabindex="-1">Prečo produkcia hovorí len „wrong input&quot;? <a class="header-anchor" href="#preco-produkcia-hovori-len-„wrong-input" aria-label="Permalink to &quot;Prečo produkcia hovorí len „wrong input&quot;?&quot;">​</a></h2><p>Detaily chýb sú v produkcii vypnuté, aj pre <code>400</code>. Pozrite si <a href="/nette-api/pr-preview/pr-184/sk/guide/errors.html#detaily-chyb">Spracovanie chýb</a>.</p><h2 id="ako-ochranim-endpoint-tokenom" tabindex="-1">Ako ochránim endpoint tokenom? <a class="header-anchor" href="#ako-ochranim-endpoint-tokenom" aria-label="Permalink to &quot;Ako ochránim endpoint tokenom?&quot;">​</a></h2><p>Použite <code>BearerTokenAuthorization</code> alebo triedu pre API kľúč s repozitárom tokenov. Pozrite si <a href="/nette-api/pr-preview/pr-184/sk/guide/authorization.html">Autorizáciu</a>.</p><h2 id="preco-moja-aplikacia-v-prehliadaci-dostava-cors-chybu" tabindex="-1">Prečo moja aplikácia v prehliadači dostáva CORS chybu? <a class="header-anchor" href="#preco-moja-aplikacia-v-prehliadaci-dostava-cors-chybu" aria-label="Permalink to &quot;Prečo moja aplikácia v prehliadači dostáva CORS chybu?&quot;">​</a></h2><p>Nastavte povolený origin a zapnite preflight. Pozrite si <a href="/nette-api/pr-preview/pr-184/sk/guide/cors.html">CORS</a>.</p><h2 id="preco-v-logu-nie-su-odpovede-401-a-429" tabindex="-1">Prečo v logu nie sú odpovede 401 a 429? <a class="header-anchor" href="#preco-v-logu-nie-su-odpovede-401-a-429" aria-label="Permalink to &quot;Prečo v logu nie sú odpovede 401 a 429?&quot;">​</a></h2><p>V 3.x presenter skončí pred loggerom. Pozrite si <a href="/nette-api/pr-preview/pr-184/sk/guide/logging.html#co-sa-loguje">Logovanie</a>.</p><h2 id="ako-publikujem-openapi" tabindex="-1">Ako publikujem OpenAPI? <a class="header-anchor" href="#ako-publikujem-openapi" aria-label="Permalink to &quot;Ako publikujem OpenAPI?&quot;">​</a></h2><p>Zaregistrujte <code>OpenApiHandler</code> ako endpoint. Pozrite si <a href="/nette-api/pr-preview/pr-184/sk/guide/openapi.html">OpenAPI</a>.</p><h2 id="ako-prejdem-z-2-x" tabindex="-1">Ako prejdem z 2.x? <a class="header-anchor" href="#ako-prejdem-z-2-x" aria-label="Permalink to &quot;Ako prejdem z 2.x?&quot;">​</a></h2><p>Postupujte podľa <a href="/nette-api/pr-preview/pr-184/sk/upgrade.html">návodu na upgrade</a> a <a href="/nette-api/pr-preview/pr-184/sk/changelog.html">changelogu</a>.</p><h2 id="je-k-dispozicii-kompletny-projekt-ktory-si-mozem-spustit" tabindex="-1">Je k dispozícii kompletný projekt, ktorý si môžem spustiť? <a class="header-anchor" href="#je-k-dispozicii-kompletny-projekt-ktory-si-mozem-spustit" aria-label="Permalink to &quot;Je k dispozícii kompletný projekt, ktorý si môžem spustiť?&quot;">​</a></h2><p>Áno, 13, testovaných v CI: pozrite si <a href="/nette-api/pr-preview/pr-184/sk/examples/">Príklady</a>.</p>',19)])])}const k=a(i,[["render",p]]);export{u as __pageData,k as default};
